PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "fach"(
   "id" int(11) not null,
   "name" varchar(100) not null,
   "kuerzel" varchar(10) not null,
   "ist_kernfach" tinyint(1) not null,
   "ist_vorrueckungsfach" tinyint(1) not null,
   primary key("id")
);
CREATE TABLE IF NOT EXISTS "klasse"(
   "id" int(11) not null,
   "name" varchar(20) not null,
   "jahrgangsstufe" int(11) not null,
   "klassenleitung_id" int(11) default NULL,
   foreign key ("klassenleitung_id") references "lehrkraft"("id"),
   primary key("id")
);
CREATE TABLE IF NOT EXISTS "lehrbefaehigung"(
   "lehrkraft_id" int(11) not null,
   "fach_id" int(11) not null,
   foreign key ("lehrkraft_id") references "lehrkraft"("id"),
   foreign key ("fach_id") references "fach"("id"),
   primary key("lehrkraft_id", "fach_id")
);
CREATE TABLE IF NOT EXISTS "lehrkraft"(
   "id" int(11) not null,
   "familienname" varchar(100) not null,
   "rufname" varchar(50) not null,
   "geburtsdatum" date not null,
   "geschlecht" varchar(1) not null,
   primary key("id")
);
CREATE TABLE IF NOT EXISTS "note"(
   "id" int(11) not null,
   "wert" int(11) not null,
   "datum" date default NULL,
   "gewicht" int(11) default 1,
   "schueler_id" int(11) not null,
   "lehrkraft_id" int(11) not null,
   "fach_id" int(11) not null,
   "pruefung_id" int(11) default NULL,
   foreign key ("schueler_id") references "schuelerin"("id"),
   foreign key ("lehrkraft_id") references "lehrkraft"("id"),
   foreign key ("fach_id") references "fach"("id"),
   foreign key ("pruefung_id") references "pruefung"("id"),
   primary key("id")
);
CREATE TABLE IF NOT EXISTS "pruefung"(
   "id" int(11) not null,
   "typ" varchar(50) default NULL,
   "laufende_nr" int(11) not null,
   "klasse" int(11) default NULL,
   "datum" date default NULL,
   "fach_id" int(11) default NULL,
   "lehrkraft_id" int(11) default NULL,
   foreign key ("klasse") references "klasse"("id"),
   foreign key ("fach_id") references "fach"("id"),
   foreign key ("lehrkraft_id") references "lehrkraft"("id"),
   primary key("id")
);
CREATE TABLE IF NOT EXISTS "schuelerin"(
   "id" int(11) not null,
   "familienname" varchar(100) not null,
   "rufname" varchar(50) not null,
   "geburtsdatum" date not null,
   "geschlecht" varchar(1) not null,
   "ist_klassensprecher" tinyint(1) not null default 0,
   "klasse_id" int(11) default NULL,
   foreign key ("klasse_id") references "klasse"("id"),
   primary key("id")
);
CREATE TABLE IF NOT EXISTS "unterrichtet"(
   "lehrkraft_id" int(11) not null,
   "fach_id" int(11) not null,
   "klasse_id" int(11) not null,
   foreign key ("lehrkraft_id") references "lehrkraft"("id"),
   foreign key ("fach_id") references "fach"("id"),
   foreign key ("klasse_id") references "klasse"("id"),
   primary key("lehrkraft_id", "fach_id", "klasse_id")
);
CREATE INDEX klassenlehrkraft on klasse(klassenleitung_id);
CREATE INDEX schueler on note(schueler_id);
COMMIT;
